(async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const out = {};
  // 进元件库
  const libBtn = [...document.querySelectorAll('.tb-actions button')].find((b) => b.textContent.trim() === '元件库');
  out.hasEntry = !!libBtn;
  libBtn?.click();
  await sleep(2000);
  out.title = document.querySelector('.lib-title')?.textContent || null;
  out.sub = document.querySelector('.lib-sub')?.textContent || null;
  out.cards = document.querySelectorAll('.lib-card').length;
  out.names = [...document.querySelectorAll('.lib-card-name')].map((e) => e.textContent);
  out.chips = [...document.querySelectorAll('.lib-chip')].map((e) => e.textContent);
  out.credit = document.querySelector('.lib-credit')?.textContent || null;
  out.imgLoaded = [...document.querySelectorAll('.lib-card img')].filter((i) => i.naturalWidth > 0).length;
  out.consoleHint = 'ok';

  // 点开一个元件看详情（挑三极管，内容最多）
  const target = [...document.querySelectorAll('.lib-card')].find((c) => (c.textContent || '').includes('三极管'))
    || document.querySelector('.lib-card');
  target?.click();
  await sleep(800);
  out.detailTitle = document.querySelector('.lib-detail h2')?.textContent || null;
  out.detailRows = [...document.querySelectorAll('.lib-row')].map((r) => r.innerText.replace(/\s+/g, ' '));
  out.mistakes = [...document.querySelectorAll('.lib-mistakes li')].map((e) => e.textContent);
  out.detailCredit = document.querySelector('.lib-credit-inline')?.textContent || null;
  out.detailImgOk = (document.querySelector('.lib-detail-figure img')?.naturalWidth || 0) > 0;

  // 搜索框
  document.querySelector('.lib-close')?.click();
  await sleep(400);
  const setV = (el, v) => { const d = Object.getOwnPropertyDescriptor(Object.getPrototypeOf(el), 'value').set; d.call(el, v); el.dispatchEvent(new Event('input', { bubbles: true })); };
  const search = document.querySelector('.lib-search');
  setV(search, '1N4001');
  await sleep(600);
  out.searchHit = [...document.querySelectorAll('.lib-card-name')].map((e) => e.textContent);
  setV(search, '不存在的元件xyz');
  await sleep(600);
  out.emptyState = document.querySelector('.lib-empty p')?.textContent || null;

  // 回工具箱
  document.querySelector('.lib-crumb-link')?.click();
  await sleep(1200);
  out.backToToolbox = !!document.querySelector('.tb-project-main');
  return JSON.stringify(out);
})()
